'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {buildGuestDocument,validateGuestDocuments,type DocumentOptions,type DocumentScope,type GuestDocuments} from '@/lib/guest-documents';
import {GuestDocumentView,guestDocumentStyles,printGuestDocument,downloadGuestDocument} from '@/components/guest-document-view';

type Props=DocumentScope&{disabled?:boolean;onBack:()=>void};
export function GuestDocumentsPanel(props:Props){return <DocumentWorkspace key={props.actor+'/'+props.tenant+'/'+props.property+'/'+props.reservation} {...props}/>}
function DocumentWorkspace({actor,tenant,property,reservation,disabled=false,onBack}:Props){
 const [data,setData]=useState<GuestDocuments|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState(''),[options,setOptions]=useState<DocumentOptions>({kind:'registration',includeContact:false,includeBilling:false});
 const sequence=useRef(0),alive=useRef(true),printing=useRef<(()=>void)|null>(null),locked=useRef(false);
 const clearPrint=useCallback(()=>{printing.current?.();printing.current=null},[]);
 useEffect(()=>{if(disabled)clearPrint()},[disabled,clearPrint]);
 const dispose=useCallback(()=>{alive.current=false;sequence.current++;clearPrint()},[clearPrint]);
 const read=useCallback(async()=>{const value=await hotelRpc<unknown>('guest_documents',{p_tenant:tenant,p_property:property,p_reservation:reservation});validateGuestDocuments(value,{actor,tenant,property,reservation});return value},[actor,tenant,property,reservation]);
 useEffect(()=>{alive.current=true;const version=++sequence.current;void read().then(value=>{if(alive.current&&version===sequence.current){setData(value);setLoading(false)}}).catch(()=>{if(alive.current&&version===sequence.current){setError('The guest document could not be verified. Refresh the preview before printing.');setLoading(false)}});return dispose},[read,dispose]);
 async function refresh(){if(disabled||locked.current)return;locked.current=true;clearPrint();const version=++sequence.current;setLoading(true);setData(null);setError('');setNotice('');try{const value=await read();if(alive.current&&version===sequence.current)setData(value)}catch{if(alive.current&&version===sequence.current)setError('The latest guest document could not be verified. Refresh again before printing.')}finally{locked.current=false;if(alive.current&&version===sequence.current)setLoading(false)}}
 const fresh=!!data&&!loading&&!error&&!disabled,model=fresh?buildGuestDocument(data,options):null;
 function choose(next:DocumentOptions){clearPrint();setOptions(next);setNotice('')}
 function print(){if(!fresh||!model)return;clearPrint();try{printing.current=printGuestDocument(model);setNotice('Printing opened for this prepared snapshot. Your browser controls printing or saving a PDF.')}catch{setError('Printing could not open. Refresh the preview before trying again.');setData(null)}}
 return <section className="guest-documents-panel"><style>{guestDocumentStyles}</style><p>Prepare a current record for the guest. This does not save or issue a document, complete registration, or move money.</p><div className="pilot-actions"><button className="secondary" disabled={disabled} onClick={()=>{clearPrint();onBack()}}>Back to reservation</button><button className="secondary" disabled={disabled||loading} onClick={()=>void refresh()}>{loading?'Preparing…':'Refresh preview'}</button><button className="primary" disabled={!fresh} onClick={print}>Print / Save as PDF</button><button className="secondary" disabled={!fresh} onClick={()=>{if(!fresh||!model)return;try{downloadGuestDocument(model);setNotice('Printable copy requested. Open the downloaded HTML file in your browser to print.')}catch{setNotice('The printable copy could not be downloaded. Try printing or refresh the preview.')}}}>Download printable copy</button></div><label className="field">Guest document<select value={options.kind} disabled={disabled} onChange={e=>choose({...options,kind:e.target.value as DocumentOptions['kind']})}><option value="registration">Registration summary</option><option value="account">Guest account statement</option></select></label><div className="pilot-guest-group"><label className="pilot-check"><input type="checkbox" checked={options.includeContact} disabled={disabled||!data?.stay_guest.recorded} onChange={e=>choose({...options,includeContact:e.target.checked})}/>Include saved contact details</label><label className="pilot-check"><input type="checkbox" checked={options.includeBilling} disabled={disabled||!data?.stay_guest.recorded} onChange={e=>choose({...options,includeBilling:e.target.checked})}/>Include intended billing recipient</label><p>Only the selected saved fields appear below and in print. Billing email and phone are excluded. These choices do not change saved stay details.</p></div>{data?.stay_guest.linked_profile_changed&&<p className="pilot-notice">The reusable guest profile has changed. This document uses this stay’s saved copy when selected.</p>}{error&&<div className="pilot-error" role="alert">{error}</div>}{notice&&<output className="pilot-notice">{notice}</output>}{model?<GuestDocumentView model={model}/>:<output className="pilot-empty">{loading?'Preparing the selected reservation snapshot…':disabled?'Finish the current workspace action before previewing or printing.':'No verified preview available.'}</output>}<p className="muted">The preparation time identifies this read. A later refresh may show changed records. The PMS does not retain an issued copy of this document.</p></section>;
}
